-- goauth:statement
CREATE TABLE "email_change_requests" ("user_id" uuid NOT NULL, "id" character varying(36) NOT NULL, "session_id" character varying(36) NOT NULL, "scope" character varying(10) NOT NULL, "current_email" character varying(255) NOT NULL, "new_email" character varying(255) NOT NULL, "current_code_hash" character varying(64) NOT NULL, "new_code_hash" character varying(64) NOT NULL, "identity_hash" character varying(64) NOT NULL, "status" character varying(16) NOT NULL, "created_at" bigint NOT NULL, "expires_at" bigint NOT NULL, "budget_started_at" bigint NOT NULL, "current_sent_at" bigint NOT NULL, "new_sent_at" bigint NOT NULL, "starts" integer NOT NULL, "attempts" integer NOT NULL, "current_resends" integer NOT NULL, "new_resends" integer NOT NULL, PRIMARY KEY ("user_id"), CONSTRAINT "email_change_requests_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);

